// The table is generated by walking the location object, so a new property adds a row
import { el, externalLink } from '../dom.js';
import { workLabel } from '../data.js';

const LABELS = {
  '@type': 'Type',
  name: 'Name',
  address: 'Address',
  geo: 'Coordinates',
  'lmml:cameraPosition': 'Camera position',
  'lmml:cameraBearing': 'Camera direction',
  'lmml:cameraConfidence': 'Camera data',
  'lmml:shotDescription': 'How to find the shot',
  'lmml:visitorAccess': 'Visiting and photography',
  'lmml:verified': 'Verified',
  'lmml:appearsIn': 'Appears in',
  'lmml:alsoAppearsIn': 'Also appears in',
  'lmml:sceneDescription': 'Scene',
  'lmml:representsPlace': 'Plays the role of',
  datePublished: 'Released',
  director: 'Director',
  author: 'Writer',
  creator: 'Created by',
  addressCountry: 'Country',
  episodeNumber: 'Episode',
  partOfSeason: 'Season',
  partOfSeries: 'Series',
  trailer: 'Trailer',
  video: 'Video clip',
  citation: 'Sources',
};

// Working data, and what the page shows elsewhere. lmml:quiz would give its answer away.
const SKIP = new Set(['@context', 'identifier', 'image', 'lmml:texts',
  'lmml:facts', 'lmml:openQuestions', 'lmml:imageNote', 'lmml:quiz']);

const WORK_TYPES = new Set(['Movie', 'TVEpisode', 'TVSeries']);

const TYPE_FORMATTERS = {
  GeoCoordinates: (v) => externalLink(
    `https://www.openstreetmap.org/?mlat=${v.latitude}&mlon=${v.longitude}#map=19/${v.latitude}/${v.longitude}`,
    `${v.latitude}, ${v.longitude}`),
  PostalAddress: (v) => [v.streetAddress, v.postalCode, v.addressLocality].filter(Boolean).join(', '),
  Person: (v) => v.name,
  Place: (v) => v.name,
  TVSeries: (v) => v.name,
  TVSeason: (v) => (v.seasonNumber != null ? `Season ${v.seasonNumber}` : null),
  CreativeWork: (v) => el('span', {}, externalLink(v.url), v.description ? ` — ${v.description}` : ''),
  VideoObject: (v) => el('span', {}, externalLink(v.url, v.name), v.publisher?.name ? ` — ${v.publisher.name}, YouTube` : ''),
};

const KEY_FORMATTERS = {
  'lmml:cameraBearing': (v) => `${v}° from north (${compass(v)})`,
  'lmml:verified': (v) => (v ? 'Yes' : 'No — to be checked'),
  'lmml:cameraConfidence': (v) => (v === 'estimated' ? 'Estimated, not yet checked on site' : String(v)),
  'lmml:visitorAccess': visitorAccess,
};

export function buildMetadataTable(loc) {
  const tbody = el('tbody');
  addRows(tbody, loc, [], true);
  return el('table', { 'data-role': 'metadata-table' },
    el('caption', { 'data-role': 'metadata-caption' }, 'Metadata'),
    tbody);
}

function addRows(tbody, obj, path, isRoot) {
  for (const [key, value] of Object.entries(obj)) {
    if (SKIP.has(key) || isEmpty(value)) continue;
    if (key === '@type' && isRoot) continue;

    const labels = [...path, labelFor(key)];
    const rendered = renderValue(key, value);

    if (rendered === undefined) {
      addRows(tbody, value, labels, false);
    } else if (rendered !== null) {
      tbody.append(
        el('tr', { 'data-key': key, 'data-depth': path.length },
          el('th', { scope: 'row' }, labels.join(' › ')),
          el('td', {}, rendered)),
      );
    }
  }
}

// null hides the row, undefined expands the object into sub-rows
function renderValue(key, value) {
  if (KEY_FORMATTERS[key]) return KEY_FORMATTERS[key](value);

  if (Array.isArray(value)) {
    return el('ul', { 'data-role': 'metadata-list' },
      value.map((item) => el('li', {}, renderListItem(key, item))));
  }
  // The main work is always expanded
  if (key === 'lmml:appearsIn') return undefined;
  if (typeof value === 'object') {
    const formatter = TYPE_FORMATTERS[value['@type']];
    return formatter ? formatter(value) : undefined;
  }
  if (typeof value === 'boolean') return value ? 'Yes' : 'No';
  if (typeof value === 'string' && /^https?:\/\//.test(value)) return externalLink(value);
  return String(value);
}

function visitorAccess(value) {
  return el('div', { 'data-role': 'visitor-access' },
    el('ul', { 'data-role': 'metadata-list' },
      (value.statements ?? []).map((s) =>
        el('li', {}, s.text, ' ', s.url && externalLink(s.url, 'Source')))),
    value.dateChecked && el('p', { 'data-role': 'date-checked' }, `Information checked on ${value.dateChecked}.`));
}

function renderListItem(key, item) {
  if (item && typeof item === 'object' && WORK_TYPES.has(item['@type'])) return workLabel(item);
  return renderValue(key, item) ?? JSON.stringify(item);
}

function isEmpty(value) {
  if (value === null || value === undefined || value === '') return true;
  if (Array.isArray(value)) return value.length === 0;
  if (typeof value === 'object') {
    return Object.entries(value).every(([k, v]) => k === '@type' || isEmpty(v));
  }
  return false;
}

// "lmml:shootingDate" -> "Shooting date"
function labelFor(key) {
  if (LABELS[key]) return LABELS[key];
  const words = key.replace(/^[a-z]+:/, '').replace(/([a-z])([A-Z])/g, '$1 $2').toLowerCase();
  return words.charAt(0).toUpperCase() + words.slice(1);
}

function compass(degrees) {
  const points = ['N', 'NE', 'E', 'SE', 'S', 'SW', 'W', 'NW'];
  const normalised = ((degrees % 360) + 360) % 360;
  return points[Math.round(normalised / 45) % 8];
}
